 const gallery=s.sections.gallery&&img.length?`<section class="section gallery-section" data-section="gallery" data-studio-id="gallery"><div class="section-top"><div><span class="eyebrow">GALERIA</span><h2>Por trás de cada detalhe.</h2></div><p>Uma seleção visual para apresentar a identidade do negócio.</p></div><div class="gallery-grid">${img.slice(0,6).map((x,i)=>`<figure><img src="${x}" alt="Imagem ${i+1}" data-studio-id="gallery-image-${i}"></figure>`).join('')}</div></section>`:'';
