 const faq=s.sections.faq?`<section class="section faq" data-section="faq" data-studio-id="faq"><div class="section-top"><div><span class="eyebrow">FAQ</span><h2>Dúvidas rápidas.</h2></div></div><div class="faq-list"><details><summary>Como funciona o atendimento?</summary><p>Entre em contato pelos canais disponíveis para receber as informações do negócio.</p></details><details><summary>Como faço um pedido ou agendamento?</summary><p>Use o botão principal ou um dos canais de contato.</p></details><details><summary>Quais são os horários?</summary><p>Consulte os horários diretamente com o estabelecimento.</p></details></div></section>`:'';
 const contacts=Object.entries(s.contacts).filter(([k,v])=>v).map(([k,v])=>{let label={whatsapp:'WhatsApp',instagram:'Instagram',facebook:'Facebook',tiktok:'TikTok',youtube:'YouTube',telegram:'Telegram',threads:'Threads',twitter:'X / Twitter',linkedin:'LinkedIn',pinterest:'Pinterest',discord:'Discord',email:'E-mail',phone:'Telefone'}[k]||k;let href=k==='phone'?'tel:'+String(v).replace(/\D/g,''):k==='email'?'mailto:'+v:v;return `<a class="contact-pill" href="${esc(href)}" target="${href.startsWith('http')?'_blank':'_self'}" rel="noopener noreferrer" data-studio-id="contact-${k}">${label}</a>`}).join('');
